"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[15521],{15521:function(n){n.exports=JSON.parse('{"content":"\\n<center>\\n<BookCard \\n          cover=\\"/assets/snippets/books/three-body-1.png\\"\\n          title=\\"삼체 1: 삼체문제\\"\\n          author=\\"류츠신\\"\\n          publisher=\\"자음과 모음\\"\\n          publishedDate=\\"2022-02-15\\"\\n          isbn=\\"9788954442695\\"\\n          rating=5\\n          tags=\\"sf\\"\\n        />\\n</center>\\n\\n## Review\\n정말 재미있게 읽었다.  \\n책 읽는 속도가 빠른 편은 아닌데, 이 책은 두꺼움에도 불구하고 금방 읽었다.  \\n<br>\\n책 초반에 우리가 지금까지 알고 있던 <b>기초 물리학</b>의 붕괴와 그로 인한 과학자들의 자살.  \\n과거와 현재 세계를 오가는 이야기와 의문 모를 가상 게임 세계.  \\n책 초반에는 이러한 이야기들이 흩뿌려진다.  \\n이때까지 어떤 이야기가 주된 이야기인지 감이 안 잡혔었다.  \\n<br>\\n하지만 중반부에 들어서면서 모든 것이 연결되기 시작한다.  \\n인상 깊었던 것은 <mark>삼체문제 (Three-body problem)</mark>라는 개념이었다.  \\n<br>\\n뒷 이야기가 궁금해서 바로 삼체 다음 시리즈를 읽었다.  "}')}}]);